"""PX1 M1 integrated interface audit, pure Python 3; run next to existing FreeCAD generator.
Outputs SVG and JSON from the SAME source parameters. No CAD/pressure certification.
"""
import ast, json, math
from pathlib import Path
root=Path(__file__).resolve().parent
source=root/"PX1_Integrated_6x6_M1_interface_repair.py"
tree=ast.parse(source.read_text(encoding="utf8"))
node=next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=="P" for t in n.targets))
assert isinstance(node,ast.Call) and isinstance(node.func,ast.Name) and node.func.id=="dict"
p={k.arg:ast.literal_eval(k.value) for k in node.keywords}
checks={}
def gate(name, ok, detail):
    checks[name]={"status":"PASS" if ok else "FAIL","detail":detail}
xs=p["stations"]; gx=p["gear_x"]; m=p["gear_m"]; wd=p["wheel_D"]; ww=p["wheel_W"]
gate("six_wheel_stations",len(xs)==3 and len(set(xs))==3,{"per_side":list(xs)})
gate("ten_gear_stations",len(gx)==5 and len(set(gx))==5,{"per_side":list(gx)})
gate("gear_pitch_geometry",all(abs(gx[i+1]-gx[i]-50*m)<1e-8 for i in range(4)),{"module_assumed":m,"centre_distance_mm":50*m})
gate("motor_motor_clearance",2*p["motor_y"]-p["motor_D"]>=2,{"gap_mm":2*p["motor_y"]-p["motor_D"]})
gate("motor_spur_clearance",p["gear_y"]-p["gear_thick"]/2-(p["motor_y"]+p["motor_D"]/2)>=2,{"gap_mm":p["gear_y"]-p["gear_thick"]/2-(p["motor_y"]+p["motor_D"]/2)})
corner=math.hypot(46+ww,wd/2)
gate("DN150_wheel_envelope",corner<=73,{"corner_radius_mm":round(corner,3),"radial_clearance_mm":round(75-corner,3)})
# A bearing ring with a running shaft clearance is not a pressure seal.
# Six nominal external seal cartridge proxies do not establish pressure capability.
checks["six_dynamic_seals_pressure_rating"]={"status":"PHYSICAL_CHECK","detail":"Seal type, shaft surface, leakage and 0.7 bar differential unverified"}
checks["idler_carrier_structural_attachment"]={"status":"NOT_RUN","detail":"Carrier proxy has no validated fasteners/load path"}
checks["gear_teeth_and_bevel_mesh"]={"status":"NOT_RUN","detail":"Pitch cylinders only; no tooth contact validation"}
checks["solid_collision_and_STEP_roundtrip"]={"status":"NOT_RUN","detail":"Requires FreeCAD execution"}
# Geometric issue: pressure at 0.7 bar loads lid; bolt mean share is not preload.
force=p["pressure_bar_max"]*1e5*170*60*1e-6
checks["lid_load"]={"status":"PASS","detail":{"force_N":round(force,1),"average_N_per_8_bolts_not_preload":round(force/8,1)}}
svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1120" height="650" viewBox="0 0 1120 650">','<rect width="1120" height="650" fill="#f7f9fc"/>','<style>text{font-family:Arial,sans-serif;fill:#17253c} .small{font-size:14px} .head{font-size:23px;font-weight:bold}</style>','<text x="45" y="45" class="head">PX1 M1 — integrated 6x6 chassis / PARAMETRIC 2D ONLY</text>','<text x="45" y="72" class="small">Assumed dimensions, mm. Gear circles = pitch proxies, NOT teeth. No STEP or pressure proof.</text>']
# Top view: X horizontal, Y vertical. Scale 2.25 px/mm.
scale=2.25; cx=490; cy=225
svg.append(f'<rect x="{cx-p["body_L"]*scale/2:.2f}" y="{cy-p["body_W"]*scale/2:.2f}" width="{p["body_L"]*scale:.2f}" height="{p["body_W"]*scale:.2f}" rx="9" fill="#d7e3ed" stroke="#364b63" stroke-width="3"/>')
for s in (-1,1):
    for x in gx:
        svg.append(f'<circle cx="{cx+x*scale:.2f}" cy="{cy+s*p["gear_y"]*scale:.2f}" r="{25*m*scale:.2f}" fill="none" stroke="#cf7e2a" stroke-dasharray="5 5" stroke-width="2"/>')
    for x in xs:
        yy=cy+s*(46+ww/2)*scale
        svg.append(f'<rect x="{cx+x*scale-wd*scale/2:.2f}" y="{yy-ww*scale/2:.2f}" width="{wd*scale:.2f}" height="{ww*scale:.2f}" rx="8" fill="#334155" stroke="#0f172a"/>')
        svg.append(f'<circle cx="{cx+x*scale:.2f}" cy="{cy+s*39*scale:.2f}" r="10" fill="#d84848"/>')
    svg.append(f'<rect x="{cx+35*scale:.2f}" y="{cy+s*14*scale-12:.2f}" width="{42*scale:.2f}" height="24" rx="10" fill="#2e8d94" opacity=".85"/>')
svg += ['<text x="45" y="410" class="head">Interfaces and unresolved physical requirements</text>','<text x="45" y="445" class="small">6 wheels | 10 Z50 pitch positions | 2 motor envelopes | 6 shaft penetrations (red)</text>','<text x="45" y="475" class="small">4 internal idler bearings: carrier mounting NOT_RUN; seal pressure rating PHYSICAL_CHECK</text>',f'<text x="45" y="505" class="small">DN150 wheel bounding corner radius: {corner:.2f} mm (clearance {75-corner:.2f} mm, analytic only)</text>',f'<text x="45" y="535" class="small">Lid separating force at {p["pressure_bar_max"]} bar on 170 x 60 mm opening: {force:.0f} N</text>','<text x="45" y="565" class="small">Motor/gear cylinders are envelopes. No real involute, shaft seal or fastener verification.</text>','<text x="45" y="610" class="small">SOURCE: PX1_Integrated_6x6_M1_interface_repair.py | Generated by M1_integrated_2d_and_checks.py</text>','</svg>']
(root/"M1_integrated_2d_and_checks.svg").write_text("\n".join(svg),encoding="utf8")
out={"source":source.name,"design_assumptions":True,"checks":checks}
(root/"M1_integrated_2d_and_checks.json").write_text(json.dumps(out,indent=2,ensure_ascii=False),encoding="utf8")
print(json.dumps(out,indent=2,ensure_ascii=False))
if any(v["status"]=="FAIL" for v in checks.values()): raise SystemExit(1)
